{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        { "speaker": "you", "text": "I'm vegan." },
        { "speaker": "partner", "text": "Are you okay with fish broth?" },
        { "speaker": "you", "text": "No, I don't eat fish broth." },
        { "speaker": "you", "text": "I can't eat meat, fish, dairy, or eggs.", "or": true },
        { "speaker": "partner", "text": "Got it." }
      ],
      "vocab": ["vegan", "meat", "fish", "dairy", "egg", "broth"]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        { "speaker": "you", "text": "Does this have meat?" },
        { "speaker": "partner", "text": "Yes, it has chicken." },
        { "speaker": "partner", "text": "No, it's vegetable only.", "or": true },
        { "speaker": "you", "text": "Does this contain fish broth?" },
        { "speaker": "partner", "text": "Yes, it does." },
        { "speaker": "partner", "text": "No, it doesn't.", "or": true },
        { "speaker": "you", "text": "What about honey?" }
      ],
      "vocab": ["chicken", "vegetable", "contain", "honey", "ingredient"]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        { "speaker": "you", "text": "I'll have the tofu salad, please." },
        { "speaker": "partner", "text": "Sure." },
        { "speaker": "you", "text": "Could I get the vegetable tempura without egg?", "or": true },
        { "speaker": "partner", "text": "We can't remove the egg from the batter." },
        { "speaker": "partner", "text": "Yes, we can do that.", "or": true },
        { "speaker": "you", "text": "I'll take edamame instead." }
      ],
      "vocab": ["tofu", "salad", "tempura", "batter", "remove", "instead"]
    }
  ]
}
